//! Agreement with WSJT-X 2.7.0-rc3's ft8sim (`fixtures/ft8/wsjtx.json`, generated by
//! `tools/wsjtx/vectors.py` from `tools/wsjtx/cases.txt`).
//!
//! For every case ft8sim packs, `pack(parse(input))` must give WSJT-X's bits, the FT8 tones its
//! channel symbols, and `unpack` of its bits its display text. The cases in [`DIFFERENCES`]
//! are inputs whose text WSJT-X changes or refuses; for those the test checks what rr73-ft8
//! does instead, and still checks that rr73-ft8 shows WSJT-X's bits as WSJT-X does.

mod common;

use rr73_ft8::message::{Callsign, Message, pack, unpack};
use rr73_ft8::{CallsignHashes, Mode, Payload, tones};
use serde::Deserialize;
use std::collections::BTreeSet;

#[derive(Deserialize)]
struct File {
    generator: String,
    vectors: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    input: String,
    text: String,
    i3: u8,
    n3: Option<u8>,
    bits: String,
    symbols: String,
}

/// What WSJT-X shows when its packer fails.
const BAD_MESSAGE: &str = "*** bad message ***";

/// What rr73-ft8 does with an input whose text WSJT-X changes or refuses.
enum Ours {
    /// `Message::parse` returns an error.
    Refuses,
    /// `Message::parse` succeeds and the message displays as given.
    Sends(&'static str),
}

/// Inputs where rr73-ft8 deliberately differs from WSJT-X 2.7.0-rc3, and why. rr73-ft8 never
/// changes what the operator typed beyond case, spacing, brackets and number format.
const DIFFERENCES: &[(&str, Ours, &str)] = &[
    (
        "K1ABC W9XYZ +99",
        Ours::Refuses,
        "WSJT-X wraps reports above +50 (sends -02)",
    ),
    (
        "K1ABC W9XYZ +51",
        Ours::Refuses,
        "WSJT-X wraps reports above +50 (sends -50)",
    ),
    (
        "K1ABC W9XYZ R -15",
        Ours::Sends("K1ABC W9XYZ R-15"),
        "WSJT-X drops an R written apart from the report",
    ),
    ("K1ABC W9XYZ R RRR", Ours::Refuses, "WSJT-X drops the R"),
    (
        "CQ K1ABC -15",
        Ours::Sends("CQ K1ABC -15"),
        "WSJT-X makes no message; the text fits free text",
    ),
    (
        "3DA0XYZ K1ABC -05",
        Ours::Sends("<3DA0XYZ> K1ABC -05"),
        "WSJT-X truncates to free text",
    ),
    (
        "3DA0X K1ABC RR73",
        Ours::Sends("3DA0X <K1ABC> RR73"),
        "WSJT-X truncates to free text",
    ),
    (
        "3XA0XYZ K1ABC 73",
        Ours::Sends("3XA0XYZ <K1ABC> 73"),
        "WSJT-X truncates to free text",
    ),
    (
        "3XZ0AB K1ABC KJ37",
        Ours::Sends("<3XZ0AB> K1ABC KJ37"),
        "WSJT-X truncates to free text",
    ),
    (
        "K1AB2 W9XYZ -05",
        Ours::Sends("<K1AB2> W9XYZ -05"),
        "WSJT-X truncates to free text",
    ),
    (
        "QA0XYZ K1ABC -05",
        Ours::Sends("QA0XYZ K1ABC -05"),
        "WSJT-X packs no Q callsign; jt9 shows one",
    ),
    (
        "Q1ABC W9XYZ -05",
        Ours::Sends("Q1ABC W9XYZ -05"),
        "WSJT-X packs no Q callsign; jt9 shows one",
    ),
    (
        "KA1 W9XYZ -05",
        Ours::Sends("KA1 W9XYZ -05"),
        "WSJT-X sends free text; jt9 shows the same text",
    ),
    (
        "R2RFE/P <EA8/G5LSI> R+12",
        Ours::Sends("R2RFE/P <EA8/G5LSI> R+12"),
        "WSJT-X drops the report",
    ),
    (
        "<PJ4/K1ABC> <W9XYZ> -05",
        Ours::Sends("<PJ4/K1ABC> <W9XYZ> -05"),
        "WSJT-X drops the report",
    ),
    (
        "PJ4/K1ABC W9XYZ -05",
        Ours::Sends("<PJ4/K1ABC> W9XYZ -05"),
        "WSJT-X drops the prefix",
    ),
    (
        "W9XYZ PJ4/K1ABC R-05",
        Ours::Sends("W9XYZ <PJ4/K1ABC> R-05"),
        "WSJT-X drops the prefix",
    ),
    (
        "W9XYZ PJ4/K1ABC RRR",
        Ours::Sends("<W9XYZ> PJ4/K1ABC RRR"),
        "WSJT-X drops the prefix",
    ),
    (
        "PJ4/K1ABC W9XYZ 73",
        Ours::Sends("PJ4/K1ABC <W9XYZ> 73"),
        "WSJT-X drops the prefix",
    ),
    ("CQ PJ4/K1ABC FN42", Ours::Refuses, "WSJT-X drops the prefix"),
    (
        "3DA0XYZ RR73; VK2AB <3Y0J> -20",
        Ours::Sends("<3DA0XYZ> RR73; VK2AB <3Y0J> -20"),
        "WSJT-X packs no hash here (truncates); jt9 shows one",
    ),
    (
        "<PJ4/K1ABC> RR73; W9XYZ <KH1/KH7Z> -12",
        Ours::Sends("<PJ4/K1ABC> RR73; W9XYZ <KH1/KH7Z> -12"),
        "WSJT-X packs no hash here (truncates); jt9 shows one",
    ),
    (
        "K1ABC RR73; <YW18FIFA> <TX5S> +04",
        Ours::Sends("K1ABC RR73; <YW18FIFA> <TX5S> +04"),
        "WSJT-X packs no hash here (truncates); jt9 shows one",
    ),
    (
        "K1ABC RR73; W9XYZ KH1/KH7Z -08",
        Ours::Sends("K1ABC RR73; W9XYZ <KH1/KH7Z> -08"),
        "WSJT-X needs brackets around the DXpedition callsign",
    ),
    (
        "K1ABC RR73; W9XYZ <KH1/KH7Z> -07",
        Ours::Refuses,
        "WSJT-X rounds odd DXpedition reports",
    ),
    (
        "K1ABC RR73; W9XYZ <KH1/KH7Z> -09",
        Ours::Refuses,
        "WSJT-X rounds odd DXpedition reports",
    ),
    (
        "K1ABC RR73; W9XYZ <KH1/KH7Z> +33",
        Ours::Refuses,
        "WSJT-X clamps DXpedition reports",
    ),
    (
        "K1ABC <PJ4/W9XYZ> 1B DX",
        Ours::Sends("K1ABC <PJ4/W9XYZ> 1B DX"),
        "WSJT-X packs no hash here (truncates); jt9 shows one",
    ),
    (
        "K1ABC <PJ4/W9XYZ> 599 1234",
        Ours::Sends("K1ABC <PJ4/W9XYZ> 599 1234"),
        "WSJT-X packs no hash here (truncates); jt9 shows one",
    ),
    (
        "K1ABC G4ABC 599 0000",
        Ours::Refuses,
        "WSJT-X truncates to free text",
    ),
    (
        "K1ABC G4ABC 599 8000",
        Ours::Refuses,
        "WSJT-X sends a serial number it then shows as nothing",
    ),
    (
        "<DL1ABC> <OK1XYZ> 520000 AA00AA",
        Ours::Sends("<DL1ABC> <OK1XYZ> 520000 AA00AA"),
        "WSJT-X truncates 520000 (but not 520001) to free text; jt9 shows it",
    ),
    (
        "<DL1ABC> <OK1XYZ> 522048 AA00AA",
        Ours::Refuses,
        "WSJT-X clamps serial numbers",
    ),
    (
        "G4ABC PA9XYZ R 570007 JO22DB",
        Ours::Sends("<G4ABC> <PA9XYZ> R 570007 JO22DB"),
        "WSJT-X needs brackets around EU VHF callsigns",
    ),
    (
        "800000000000000000",
        Ours::Refuses,
        "WSJT-X truncates to free text",
    ),
    (
        "THIS IS FAR TOO LONG FOR FT8",
        Ours::Refuses,
        "WSJT-X truncates to 13 characters",
    ),
];

fn payload(bits: &str) -> Payload {
    Payload::from_bits(&bits.bytes().map(|b| b - b'0').collect::<Vec<_>>())
}

fn symbols(mode: Mode, p: &Payload) -> String {
    tones::from_payload(mode, p)
        .iter()
        .map(|t| char::from(b'0' + t))
        .collect()
}

/// A hash table holding the callsigns of `input` in the order they appear, as ft8sim's own
/// table holds them when it shows the message.
fn table_of(input: &str) -> CallsignHashes {
    let mut table = CallsignHashes::new();
    for word in input.split_whitespace() {
        if let Ok(call) = Callsign::new(word.trim_start_matches('<').trim_end_matches('>')) {
            table.insert(&call);
        }
    }
    table
}

#[test]
fn the_case_list_covers_every_message_type() {
    let file: File = common::load("wsjtx.json");
    assert!(file.generator.contains("WSJT-X 2.7.0-rc3"), "{}", file.generator);
    assert!(file.vectors.len() >= 80, "{}", file.vectors.len());
    let types: BTreeSet<(u8, Option<u8>)> = file
        .vectors
        .iter()
        .map(|c| (c.i3, if c.i3 == 0 { c.n3 } else { None }))
        .collect();
    for t in [
        (0, Some(0)),
        (0, Some(1)),
        (0, Some(3)),
        (0, Some(4)),
        (0, Some(5)),
        (1, None),
        (2, None),
        (3, None),
        (4, None),
        (5, None),
    ] {
        assert!(types.contains(&t), "{t:?}: {types:?}");
    }
    let inputs: BTreeSet<&str> = file.vectors.iter().map(|c| c.input.as_str()).collect();
    for (input, _, _) in DIFFERENCES {
        assert!(inputs.contains(input), "{input} is not in the case list");
    }
}

#[test]
fn pack_gives_wsjtx_bits_and_channel_symbols() {
    let file: File = common::load("wsjtx.json");
    let mut agreed = 0;
    for c in &file.vectors {
        let parsed = Message::parse(&c.input);
        if let Some((_, ours, reason)) = DIFFERENCES.iter().find(|(input, _, _)| *input == c.input) {
            match ours {
                Ours::Refuses => assert!(parsed.is_err(), "{}: {reason}; parsed as {parsed:?}", c.input),
                Ours::Sends(text) => {
                    let m = parsed.unwrap_or_else(|e| panic!("{}: {e}", c.input));
                    assert_eq!(m.to_string(), *text, "{}: {reason}", c.input);
                    let p =
                        pack(&m, &mut CallsignHashes::new()).unwrap_or_else(|e| panic!("{}: {e}", c.input));
                    assert_ne!(p, payload(&c.bits), "{} is listed as a difference", c.input);
                }
            }
            continue;
        }
        if c.text == BAD_MESSAGE {
            // WSJT-X makes no message: neither does rr73-ft8.
            assert!(
                parsed.is_err(),
                "{}: WSJT-X refuses it; parsed as {parsed:?}",
                c.input
            );
            continue;
        }
        let m = parsed.unwrap_or_else(|e| panic!("{}: {e}", c.input));
        let p = pack(&m, &mut CallsignHashes::new()).unwrap_or_else(|e| panic!("{}: {e}", c.input));
        assert_eq!(p, payload(&c.bits), "{} packs as {m}", c.input);
        assert_eq!(symbols(Mode::Ft8, &p), c.symbols, "{}", c.input);
        let (i3, n3) = m.i3_n3();
        assert_eq!(i3, c.i3, "{}", c.input);
        if i3 == 0 {
            assert_eq!(Some(n3), c.n3, "{}", c.input);
        }
        agreed += 1;
    }
    assert!(agreed >= 300, "{agreed}");
}

#[test]
fn unpack_shows_what_wsjtx_shows() {
    let file: File = common::load("wsjtx.json");
    for c in &file.vectors {
        let shown = unpack(&payload(&c.bits), &table_of(&c.input)).map(|m| m.to_string());
        match c.text.as_str() {
            // ft8sim prints zero bits when its packer fails.
            BAD_MESSAGE => assert!(shown.is_err(), "{}: {shown:?}", c.input),
            // WSJT-X shows nothing for telemetry 0 and for serial number 8000. rr73-ft8 shows
            // telemetry 0 as "0" and rejects serial number 8000.
            "" if c.input == "0" => assert_eq!(shown, Ok("0".to_string())),
            "" => assert!(shown.is_err(), "{}: {shown:?}", c.input),
            text => assert_eq!(shown.as_deref(), Ok(text), "{}", c.input),
        }
    }
}
